// FSC-parity: a minimalist custom scrollbar - "Fixed 80px track with
// proportional thumb. Fades in on scroll. Always visible on touch." Applied
// to any element with [data-hemma-scrollbar]; the element keeps its native
// scrolling (this only draws a themed overlay thumb+track and hides the
// native bar), so touch/wheel/keyboard scrolling all keep working untouched.
(function () {
  if (window._hemmaScrollbarInit) return;
  window._hemmaScrollbarInit = true;

  var TRACK = 80;           // px, fixed track length per FSC's spec
  var THICKNESS = 4;        // px
  var FADE_MS = 900;        // how long the thumb stays after scrolling stops
  var isTouch = window.matchMedia && window.matchMedia('(hover: none) and (pointer: coarse)').matches;

  function build(el) {
    if (el._hemmaScrollbar) return el._hemmaScrollbar;
    var track = document.createElement('div');
    var thumb = document.createElement('div');
    track.className = 'hemma-scrollbar-track';
    thumb.className = 'hemma-scrollbar-thumb';
    track.style.cssText = 'position:absolute; top:0; right:2px; width:' + THICKNESS
      + 'px; height:' + TRACK + 'px; border-radius:' + (THICKNESS / 2)
      + 'px; pointer-events:none; opacity:0; transition:opacity .25s ease; z-index:3;';
    thumb.style.cssText = 'position:absolute; left:0; width:100%; border-radius:'
      + (THICKNESS / 2) + 'px; background:var(--hemma-scrollbar-thumb, rgba(255,255,255,0.45));';
    track.appendChild(thumb);
    var host = el;
    if (getComputedStyle(host).position === 'static') host.style.position = 'relative';
    host.appendChild(track);
    host.classList.add('hemma-scrollbar-host');
    el._hemmaScrollbar = { track: track, thumb: thumb };
    return el._hemmaScrollbar;
  }

  function update(el) {
    var sb = build(el);
    var max = el.scrollHeight - el.clientHeight;
    if (max <= 1) { sb.track.style.opacity = '0'; return; }
    // Track centers on the viewport, not the full scroll range, matching a
    // fixed-length indicator rather than a shrink-to-fit native thumb.
    var centerY = el.clientHeight / 2 - TRACK / 2;
    sb.track.style.top = Math.max(0, Math.min(el.clientHeight - TRACK, centerY)) + 'px';
    var progress = el.scrollTop / max;
    var thumbLen = Math.max(18, TRACK * Math.min(1, el.clientHeight / el.scrollHeight));
    sb.thumb.style.height = thumbLen + 'px';
    sb.thumb.style.top = (progress * (TRACK - thumbLen)) + 'px';
    sb.track.style.opacity = '1';
    clearTimeout(el._hemmaScrollbarFade);
    if (!isTouch) {
      el._hemmaScrollbarFade = setTimeout(function () {
        sb.track.style.opacity = '0';
      }, FADE_MS);
    }
  }

  function watch(el) {
    if (!el || el._hemmaScrollbarWatched) return;
    el._hemmaScrollbarWatched = true;
    el.style.scrollbarWidth = 'none';          // Firefox
    el.style.msOverflowStyle = 'none';         // old Edge
    var style = document.createElement('style');
    style.textContent = '.hemma-scrollbar-host::-webkit-scrollbar { display: none; }';
    (el.shadowRoot || el.ownerDocument.head).appendChild(style);
    el.addEventListener('scroll', function () { update(el); }, { passive: true });
    if (typeof ResizeObserver === 'function') {
      new ResizeObserver(function () { update(el); }).observe(el);
    }
    update(el);
  }

  function scan(root) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('[data-hemma-scrollbar]').forEach(watch);
  }

  scan(document);
  var mo = new MutationObserver(function (muts) {
    muts.forEach(function (m) {
      if (!m.addedNodes) return;
      m.addedNodes.forEach(function (n) {
        if (n.nodeType !== 1) return;
        if (n.hasAttribute && n.hasAttribute('data-hemma-scrollbar')) watch(n);
        scan(n);
        if (n.shadowRoot) scan(n.shadowRoot);
      });
    });
  });
  mo.observe(document.documentElement, { childList: true, subtree: true });

  window._hemmaScrollbarRescan = scan;
})();
